SWASTHYA_SETU_POSTER_URI = "data:image/jpeg;base64," + SWASTHYA_SETU_POSTER_B64
SWASTHYA_SETU_LOGO_URI = "data:image/png;base64," + SWASTHYA_SETU_LOGO_B64
SWASTHYA_SETU_LOGO_BYTES = base64.b64decode(SWASTHYA_SETU_LOGO_B64)


def render_corner_logo():
    """Show the Swasthya Setu logo in the top-right corner on every app page."""
    st.markdown(
        f"""
        <div class="ss-corner-logo" title="Swasthya Setu">
            <img src="__SS_LOGO_URI__" alt="Swasthya Setu logo">
        </div>
        """.replace("__SS_LOGO_URI__", SWASTHYA_SETU_LOGO_URI),
        unsafe_allow_html=True
    )


def show_intro_screen():
    """Display the supplied animated Swasthya Setu intro before the prototype."""
    intro_html = """
    <style>
        @keyframes ssFloat {
            0% { transform: translateY(0) scale(1); }
            50% { transform: translateY(-10px) scale(1.015); }
            100% { transform: translateY(0) scale(1); }
        }
        @keyframes ssGlow {
            0%, 100% { box-shadow: 0 12px 35px rgba(255, 119, 0, 0.18); }
            50% { box-shadow: 0 20px 55px rgba(255, 119, 0, 0.38); }
        }
        .ss-intro-wrap {
            min-height: 82vh;
            display:flex;
            align-items:center;
            justify-content:center;
            padding:18px;
            box-sizing:border-box;
            background:transparent;
        }
        .ss-intro-card {
            width:min(760px, 94vw);
            background:#fff;
            border:3px solid rgba(255,153,51,.42);
            border-radius:30px;
            overflow:hidden;
            animation:ssGlow 3.5s ease-in-out infinite;
        }
        .ss-intro-img {
            width:100%;
            max-height:68vh;
            object-fit:contain;
            display:block;
            animation:ssFloat 3.5s ease-in-out infinite;
        }
        .ss-intro-caption {
            text-align:center;
            padding:16px 20px 22px;
            color:#17345f;
            font-family:Segoe UI, Arial, sans-serif;
        }
        .ss-intro-caption .hi {
            color:#1d4f91;
            font-size:24px;
            font-weight:800;
            margin:4px 0;
        }
        .ss-intro-caption .en {
            color:#4b5563;
            font-size:14px;
            font-weight:600;
        }
    </style>
    <div class="ss-intro-wrap">
        <div class="ss-intro-card">
            <img class="ss-intro-img" src="__SS_POSTER_URI__" alt="Swasthya Setu">
            <div class="ss-intro-caption">
                <div class="hi">स्वास्थ्य सेतु — स्वास्थ्य भारत, सुरक्षित भारत</div>
                <div class="en">Connecting Patients, Doctors &amp; Healthcare Across India</div>
            </div>
        </div>
    </div>
    """
    st.html(intro_html.replace("__SS_POSTER_URI__", SWASTHYA_SETU_POSTER_URI))


