def bt(key):
    return BOOKING_TEXT[st.session_state.language][key]


# ============================================================
# VOICE RECOGNITION — PRESERVED FROM TEAMMATE'S CODE
# ============================================================

def record_voice(language_choice):
    recognizer = sr.Recognizer()
    lang_code = "hi-IN" if language_choice == "Hindi" else "en-US"

    with sr.Microphone() as source:
        st.info("🎙️ Sun raha hu... Abhi boliye! (Listening...)")
        recognizer.adjust_for_ambient_noise(source, duration=0.8)

        try:
            audio = recognizer.listen(
                source,
                timeout=8,
                phrase_time_limit=15
            )
            st.success("⚡ Process kar raha hu...")
            text = recognizer.recognize_google(
                audio,
                language=lang_code
            )
            return text

        except sr.WaitTimeoutError:
            st.error("❌ Time out: Aapne kuch bola nahi.")

        except sr.UnknownValueError:
            st.error("❌ Aawaaz samajh nahi aayi. Kripya dubara boliye.")

        except Exception:
            st.error("❌ Microphone error. Kripya mic access check karein.")

    return None


