def get_doctors(city, specialization):
    names = DOCTORS.get(city, {}).get(specialization, [])
    result = []

    for i, name in enumerate(names):
        result.append({
            "name": name,
            "specialization": specialization,
            "floor": FLOORS[specialization],
            "cabin": CABINS[specialization][i],
            "slots": SLOTS[specialization]
        })

    return result


def generate_token():
    return f"A-{random.randint(100, 999)}"


